param([Parameter(Mandatory=$true)][ValidateSet('smoke','coarse','half')][string]$Window,[Parameter(Mandatory=$true)][string]$Admission,[switch]$ExecutionAuthorized)
# Exactly one CPU8 Release project-main run; never build, decode, restart or queue another job.
$ErrorActionPreference='Stop';$Window=$Window.ToLowerInvariant();$tests=Split-Path -Parent $PSScriptRoot;$repo=(Get-Item -LiteralPath $tests).Parent.Parent.Parent.Parent.FullName;$src=Join-Path $repo 'src';$logs=Join-Path $tests 'logs';$tag='upl_damp_step_CPU_'+$Window+'_r1'
$folder=Join-Path $tests ('outputs\'+$tag);$record=Join-Path $logs ($tag+'.run.json');$callPath=Join-Path $logs ($tag+'.call.json');$log=Join-Path $logs ($tag+'.log')
function E([string]$p){$f=Get-Item -LiteralPath $p -Force;[ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function J([string]$p){[IO.File]::ReadAllText($p)|ConvertFrom-Json}
function Need([bool]$ok,[string]$why){if(!$ok){throw $why}}
function V($rows){
  $seen=@{} # Per-pass only: before/after validation remains independent.
  foreach($e in $rows){
    Need ($e.path -and $null -ne $e.bytes -and $e.sha256) 'Missing bound Entry'
    $key=[IO.Path]::GetFullPath([string]$e.path)
    if($seen.ContainsKey($key)){Need ($seen[$key].bytes -eq $e.bytes -and $seen[$key].sha256 -ieq $e.sha256) ('Conflicting duplicate Entry: '+$e.path);continue}
    $a=E $e.path;Need ($a.bytes -eq $e.bytes -and $a.sha256 -ieq $e.sha256) ('Changed artifact: '+$e.path);$seen[$key]=$a
  }
}
function Fresh($paths){foreach($p in $paths){Need (!(Test-Path -LiteralPath $p)) ('Retained path protected: '+$p)}}
function Save([string]$p,$v){Fresh @($p);[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 18)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}
Need $ExecutionAuthorized.IsPresent 'Explicit root execution authorization required';Fresh @($folder,$record,$callPath,$log)
$gate=J $Admission;Need ($gate.stage -ceq 'upl_damp_step_admission_r1' -and $gate.passed -and @($gate.allowed_jobs).Count -eq 1 -and $gate.allowed_jobs[0] -ceq $tag -and $gate.physical_acceptance -eq $false -and @($gate.inputs).Count -gt 0) 'Only this single explicitly admitted step-candidate job may run';V $gate.inputs
$buildPath=Join-Path $logs 'upl_damp_ReleaseCPU_r2.build.json';$b=J $buildPath
Need ($b.passed -and $b.stage -ceq 'upl_damp_build_r2' -and $b.configuration -ceq 'ReleaseCPU' -and $b.source_bindings_unchanged -and $b.canonical_programs_unchanged -and $b.runtime_unchanged -and $b.exact_object_basename_closure -and @($b.objects).Count -eq 86 -and @($b.source_snapshot).Count -eq 265 -and @($b.canonical_programs_before).Count -eq 7 -and @($b.runtime).Count -eq 4) 'Current same ReleaseCPU authoritative main required'
$project=J $b.project_call.path;Need ($project.typed_LASTEXITCODE_captured_immediately -and $project.owned_call_exited -and $project.exit_code -is [int] -and $project.exit_code -eq 0 -and !$project.invocation_failure) 'Current authoritative build typed exit0 required'
$manifest=Join-Path $logs 'upl_damp_step_r1.inputs.json';$m=J $manifest;Need ($m.stage -ceq 'upl_damp_step_prepare_r1' -and $m.passed -and $m.prepared -and !$m.physical_acceptance) 'Own prepared step-candidate inputs required';$inputWindow=if($Window -ceq 'smoke'){'coarse'}else{$Window};$rows=@($m.jobs|Where-Object{$_.window -ceq $inputWindow});Need ($rows.Count -eq 1) 'Unique step-candidate input required';$job=$rows[0];Need ($m.source_build.sha256 -ceq (E $buildPath).sha256 -and $m.source_program.sha256 -ceq $b.program.sha256 -and $m.new_experiment -and !$m.old_half_or_prefix_adopted) 'Own Prepare must name the current program/build and a new experiment'
$dt=[Math]::Pow(2,$(if($Window -ceq 'half'){-19}else{-18}));$fullSteps=if($Window -ceq 'half'){262144}else{131072};$steps=if($Window -ceq 'smoke'){2}else{$fullSteps};$samples=if($Window -ceq 'smoke'){2}else{1341};$end=if($Window -ceq 'smoke'){2*$dt}else{0.5}
Need ($job.dt_s -eq $dt -and $job.steps -eq $fullSteps -and $job.end_s -eq 0.5 -and $job.expected_samples -eq 1341 -and @($job.saved_clock_table).Count -eq 1341 -and $job.damping -eq 1 -and $job.damping_coef -eq 0.02 -and $job.inverse_DOM_exact -and $job.only_declared_clock_event_changes -and !$job.old_trajectory_prefix_equivalence_claimed -and $job.event_completed_step -eq $(if($Window -ceq 'half'){5242}else{2621}) -and $job.event_part -eq 141) 'Locked new experiment window/material declaration differs'
$priorNative=$null;$priorBindings=@();if($Window -cne 'smoke'){
  $priorWindow=if($Window -ceq 'half'){'coarse'}else{'smoke'};$priorNative=E (Join-Path $logs ('upl_damp_step_CPU_'+$priorWindow+'_r1.native.json'));$p=J $priorNative.path;$pc=J $p.reader_call.path;$pr=J $p.source_run.path
  Need ($p.passed -and $p.stage -ceq 'upl_damp_step_native_run_r1' -and $p.window -ceq $priorWindow -and $p.bindings_unchanged -and $p.original_native_guards_passed -and $p.source_build.sha256 -ceq (E $buildPath).sha256 -and $pr.passed -and $pr.stage -ceq 'upl_damp_step_run_r1' -and $pr.window -ceq $priorWindow -and $pc.direct_native_call -and $pc.typed_LASTEXITCODE_captured_immediately -and $pc.owned_call_exited -and $pc.exit_code -is [int] -and $pc.exit_code -eq 0 -and !$pc.invocation_failure) 'Own prior smoke/coarse Run and native safety must pass first'
  Need (@($gate.inputs|Where-Object{$_.path -ceq $priorNative.path -and $_.bytes -eq $priorNative.bytes -and $_.sha256 -ceq $priorNative.sha256}).Count -eq 1) 'Per-job root admission must bind the exact own prior native check'
  $priorBindings=@($priorNative,$p.source_run,$p.reader_call,$p.completion,$pc.program,$pc.log)+@($p.inputs)+@($p.files)
}
$bindings=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_damp_step_run_r1.json')),(E (Join-Path $tests 'notes\upl_damp_step_r1.json')),(E $Admission),(E $buildPath),$b.project_call,$b.log,$b.binlog,(E $manifest),$b.program,$job.configuration,$job.runtime,$job.initial_BI4,$job.normals)+@($gate.inputs)+$priorBindings+@($m.inputs)+@($m.files)+@($b.inputs)+@($b.tools)+@($b.objects)+@($b.canonical_programs_before)+@($b.runtime_before)
foreach($p in @($b.source_snapshot)+@($b.documentation_snapshot,$b.case_readme_snapshot)){$bindings+=@($p.original,$p.snapshot)};foreach($p in $b.runtime){$bindings+=@($p.original,$p.copy)}
$argsTarget=@('-cpu','-ompthreads:8','-stable','-mdbc_freeslip',$job.input_prefix,$folder,'-dirdataout','data','-svres',('-nsteps:'+$steps))
V $bindings;$active=@(Get-CimInstance Win32_Process -Filter "Name LIKE 'DualSPHysics%.exe' OR Name LIKE 'upl_%.exe'");Need ($active.Count -eq 0) 'Another project solver/helper is active; no duplicate launch'
$started=[DateTime]::UtcNow.ToString('o');$code=$null;$failure=$null;$saved=$ErrorActionPreference;[IO.File]::WriteAllBytes($log,[byte[]]@());Push-Location $src
try{$ErrorActionPreference='Continue';$global:LASTEXITCODE=$null;& $b.program.path @argsTarget 2>&1|Tee-Object -FilePath $log -Append|Out-Host;$code=$LASTEXITCODE}catch{$failure=$_.Exception.Message}finally{Pop-Location;$ErrorActionPreference=$saved}
Save $callPath ([ordered]@{program=$b.program;target_program=$b.program;arguments=$argsTarget;target_arguments=$argsTarget;working_directory=$src;started_utc=$started;ended_utc=[DateTime]::UtcNow.ToString('o');direct_native_call=$true;typed_LASTEXITCODE_captured_immediately=($code -is [int]);owned_call_exited=($code -is [int]);exit_code=$code;invocation_failure=$failure;log=(E $log);public_project_main=$true;fixture_or_Run_override=$false;direct_target_call=$true;memcheck_executed=$false;physical_acceptance=$false})
# Seal the original typed program result before checking output; failed analysis never reruns the solver.
$files=@();$runOut=$null;$unchanged=$false;$loop=$null;$total=$null;$rawCount=0;$rate=$null
try{
  Need ($code -is [int] -and $code -eq 0 -and !$failure) 'Owned actual call failed; retain partials'
  $runOut=E (Join-Path $folder 'Run.out');$text=[IO.File]::ReadAllText($runOut.path);Need ($text -match '(?m)^\[Simulation finished\s' -and $text -match 'OpenMP\(Threads:8\)') 'Normal CPU8 completion missing'
  foreach($label in @('Simulation Runtime','Total Runtime')){$v=[regex]::Match($text,('(?m)^'+$label+'[.]+:\s*([0-9.]+)\s+sec[.]\s*$'));Need $v.Success ('Actual runtime missing: '+$label);$seconds=[double]::Parse($v.Groups[1].Value,[Globalization.CultureInfo]::InvariantCulture);if($label -ceq 'Simulation Runtime'){$loop=$seconds}else{$total=$seconds}}
  $v=[regex]::Match($text,'Dynamic soil damping rate: ([0-9.eE+-]+) s\^-1');Need $v.Success 'Actual damping-rate diagnostic missing';$rate=[double]::Parse($v.Groups[1].Value,[Globalization.CultureInfo]::InvariantCulture);Need ($rate -gt 30 -and $rate -lt 32) 'Original eta.02 candidate differs'
  $raw=@(Get-ChildItem -LiteralPath (Join-Path $folder 'data') -File -Filter 'Part_*.bi4');$rawCount=$raw.Count;$wanted=@(0..($samples-1)|ForEach-Object{'Part_{0:D4}.bi4' -f $_});Need ($rawCount -eq $samples -and !(Compare-Object ($raw.Name|Sort-Object) ($wanted|Sort-Object))) 'Declared2/1341 native sequence differs'
}catch{$failure=$_.Exception.Message}
try{V $bindings;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}};if(Test-Path -LiteralPath $folder){$files=@(Get-ChildItem -LiteralPath $folder -File -Recurse|Sort-Object FullName|ForEach-Object{E $_.FullName})}
$passed=(!$failure -and $unchanged -and $rawCount -eq $samples)
Save $record ([ordered]@{stage='upl_damp_step_run_r1';passed=[bool]$passed;backend='CPU';threads=8;window=$Window;configuration='ReleaseCPU';program=$b.program;source_build=(E $buildPath);source_snapshot=$b.source_snapshot;documentation_snapshot=$b.documentation_snapshot;case_readme_snapshot=$b.case_readme_snapshot;runtime=$b.runtime;canonical_programs_before=$b.canonical_programs_before;input_manifest=(E $manifest);job=$job;input_window=$inputWindow;planned_completed_steps=$steps;planned_end_s=$end;expected_native_frames=$samples;smoke_initial_and_terminal_only=($Window -ceq 'smoke');admission=(E $Admission);prior_native_check=$priorNative;call=(E $callPath);inputs=$bindings;files=$files;run_out=$runOut;native_frames=$rawCount;actual_damping_rate_s_inv=$rate;simulation_runtime_s=$loop;total_runtime_s=$total;source_inputs_objects_runtime_canonical_unchanged=$unchanged;public_project_main=$true;fixture_or_Run_override=$false;native_decoder_invoked=$false;old_trajectory_prefix_adopted=$false;independent_half_or_cross_performed=$false;physical_acceptance=$false;failure=$failure})
if(!$passed){throw "Step-candidate actual run rejected; retain $record, no automatic retry"};Write-Output "One CPU8 step-candidate run sealed: $record"
